def _parse_aggregate(spec):
    """(function, column or None) from `count` or `FUNCTION:COLUMN`; UsageError for anything else."""
    if spec == "count":
        return "count", None
    function, colon, column = spec.partition(":")
    if function not in GROUP_FUNCTIONS or not colon or not column:
        raise UsageError("group: %r is not an aggregate (count, sum:COLUMN, min:COLUMN, max:COLUMN or mean:COLUMN)" % spec)
    return function, column


def _aggregate(function, numbers, count):
    """One group's result cell. Sums run in a context wide enough to lose no digit."""
    if function == "count":
        return str(count)
    if function in ("min", "max"):
        return fmt_decimal((min if function == "min" else max)(numbers))
    digits = sum(len(n.as_tuple().digits) for n in numbers) + 10
    context = Context(prec=digits)
    total = Decimal(0)
    for n in numbers:
        total = context.add(total, n)
    if function == "sum":
        return fmt_decimal(total)
    return fmt_2dp(Context(prec=digits + len(str(count))).divide(total, Decimal(count)))


def cmd_group(args, opts):
    _need_at_least(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: the same aggregate is given twice")
    aggregates = [_parse_aggregate(a) for a in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    positions = [None if column is None else table.index(column) for _, column in aggregates]
    names = [spec.replace(":", "_") for spec in args[2:]]
    result_columns = [table.columns[by]] + names
    for name in result_columns:
        if result_columns.count(name) > 1:
            raise TabulaError("group: the result would have column %r twice" % name)
    groups = {}  # BY value -> [row count, one list of numbers per aggregate]
    for number, row in enumerate(table.rows, 1):
        group = groups.setdefault(row[by], [0, [[] for _ in aggregates]])
        group[0] += 1
        for (_, column), at, found in zip(aggregates, positions, group[1]):
            if at is not None:
                found.append(_cell_number(table, number, column, row[at]))
    rows = [[value] + [_aggregate(function, found, count) for (function, _), found in zip(aggregates, numbers)]
            for value, (count, numbers) in groups.items()]
    return Table(result_columns, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    left_at, right_at = left.index(args[2]), right.index(args[2])
    kept = [i for i in range(len(right.columns)) if i != right_at]
    columns = left.columns + [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i]
                              for i in kept]
    for name in columns:
        if columns.count(name) > 1:
            raise TabulaError("join: the result would have column %r twice" % name)
    matches = {}  # KEY text -> the RIGHT rows with it, in the order of RIGHT
    for row in right.rows:
        matches.setdefault(row[right_at], []).append([row[i] for i in kept])
    unmatched = [[""] * len(kept)] if opts["kind"] == "left" else []
    rows = [lrow + rrow for lrow in left.rows for rrow in matches.get(lrow[left_at], unmatched)]
    return Table(columns, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    row_at, column_at, value_at = table.index(args[1]), table.index(args[2]), table.index(args[3])
    sums = {}  # (ROW value, COLUMN value) -> the numbers to add
    row_values, column_values = {}, {}  # first-appearance order
    for number, row in enumerate(table.rows, 1):
        label = row[column_at]
        if label.strip() == "":
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, number, args[2]))
        if label == table.columns[row_at]:
            raise TabulaError("%s: row %d: column %r: value %r is the name of the row column"
                              % (table.source, number, args[2], label))
        found = _cell_number(table, number, args[3], row[value_at])
        row_values.setdefault(row[row_at])
        column_values.setdefault(label)
        sums.setdefault((row[row_at], label), []).append(found)
    rows = [[value] + [_aggregate("sum", sums[(value, label)], 0) if (value, label) in sums else "0"
                       for label in column_values] for value in row_values]
    return Table([table.columns[row_at]] + list(column_values), rows, table.source)


def cmd_dedupe(args, opts):
    _need_at_least(args, 2, "dedupe FILE KEY...")
    table = load(args[0])
    positions = [table.index(key) for key in args[1:]]
    chosen = {}  # KEY cells -> position of the row that stays (the first or the last one with them)
    for number, row in enumerate(table.rows):
        cells = tuple(row[at] for at in positions)
        if opts["keep"] == "last" or cells not in chosen:
            chosen[cells] = number
    staying = set(chosen.values())
    return table.with_rows([row for number, row in enumerate(table.rows) if number in staying])


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "rows sorted by KEYs (COLUMN[:num][:desc])"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "rows where every COLUMN OP VALUE holds (== != >= <= > < ~)"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per BY value: count, sum:COL, min:COL, max:COL, mean:COL"),
    "join": (cmd_join, "join LEFT RIGHT KEY", "LEFT rows with the RIGHT rows of the same KEY (--kind inner|left)"),
    "pivot": (cmd_pivot, "pivot FILE ROW COLUMN VALUE", "sums of VALUE, one row per ROW value, one column per COLUMN value"),
    "dedupe": (cmd_dedupe, "dedupe FILE KEY...", "drop rows repeating the KEY columns (--keep first|last)"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS..." % PROG, "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = {name: values[0] for name, values in OPTIONS.items()}, [], 0
    while i < len(argv):
        arg = argv[i]
        name, has_value, value = arg[2:].partition("=")
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif arg.startswith("--") and name in OPTIONS:
            if not has_value:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in OPTIONS[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(OPTIONS[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def _drop_stdout():
    """Point standard output at the null device so the flush at exit cannot fail again."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        _drop_stdout()
        return 0
    except OSError as exc:  # standard output cannot be written (a full disk, a closed descriptor)
        _drop_stdout()
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1
